  <script>
    // ── Search ────────────────────────────────────────────
    document.getElementById('search-form').addEventListener('submit', function (e) {
      e.preventDefault();
      const q = document.getElementById('site-search').value.trim();
      if (q) {
        window.location.href = '/search?q=' + encodeURIComponent(q);
      }
    });

    // ── Cookie banner ─────────────────────────────────────
    const banner = document.getElementById('cookie-banner');

    function dismissBanner() {
      banner.classList.add('hiding');
      setTimeout(function () {
        banner.classList.add('hidden');
      }, 260);
    }

    document.getElementById('dismiss-banner-btn').addEventListener('click', dismissBanner);

    // ── Modal ─────────────────────────────────────────────
    const modal   = document.getElementById('cookie-modal');
    let lastFocus = null;

    function openModal() {
      lastFocus = document.activeElement;
      modal.classList.add('open');
      document.body.style.overflow = 'hidden';
      // Move focus into modal
      document.getElementById('modal-close-btn').focus();
    }

    function closeModal() {
      modal.classList.remove('open');
      document.body.style.overflow = '';
      if (lastFocus) lastFocus.focus();
    }

    document.getElementById('manage-prefs-btn').addEventListener('click', openModal);
    document.getElementById('modal-close-btn').addEventListener('click', closeModal);

    // Close on backdrop click
    modal.addEventListener('click', function (e) {
      if (e.target === modal) closeModal();
    });

    // Close on Escape
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && modal.classList.contains('open')) closeModal();
    });

    // Trap focus within modal
    modal.addEventListener('keydown', function (e) {
      if (e.key !== 'Tab') return;
      const focusable = modal.querySelectorAll(
        'button:not([disabled]), input:not([disabled]), a[href], [tabindex]:not([tabindex="-1"])'
      );
      const first = focusable[0];
      const last  = focusable[focusable.length - 1];
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    });

    // Accept all
    document.getElementById('accept-all-btn').addEventListener('click', function () {
      document.getElementById('pref-analytics').checked       = true;
      document.getElementById('pref-personalization').checked = true;
      document.getElementById('pref-advertising').checked     = true;
      saveAndClose();
    });

    // Save preferences
    document.getElementById('save-prefs-btn').addEventListener('click', saveAndClose);

